using System;using System.Collections.Generic;public class WordDistance{Dictionary<string,List<int>>m=new();public WordDistance(string[]w){for(int i=0;i<w.Length;i++){if(!m.ContainsKey(w[i]))m[w[i]]=new();m[w[i]].Add(i);}}public int Shortest(string a,string b){var x=m[a];var y=m[b];int i=0,j=0,r=int.MaxValue;while(i<x.Count&&j<y.Count){r=Math.Min(r,Math.Abs(x[i]-y[j]));if(x[i]<y[j])i++;else j++;}return r;}}
